; ============================================== sub dumpBoxes ====

dumpBoxes:
; ---- for ( u16 i = 0; i < elCount; i++ ) {
        mov     word [dumpBoxes__i], 0
.L550:
        mov     ax, [dumpBoxes__i]
        mov     bx, [elCount]
        cmp     ax, bx
        jb      .L553                       ; unsigned <
        jmp     .L552
.L553:
; ---- putField( i )
        mov     ax, [dumpBoxes__i]
        mov     [putField__n], ax
        call    putField
; ---- putField( el[i].x )
        mov     ax, [dumpBoxes__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [el__x + bx]
        mov     [putField__n], ax
        call    putField
; ---- putField( el[i].y )
        mov     ax, [dumpBoxes__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [el__y + bx]
        mov     [putField__n], ax
        call    putField
; ---- putField( el[i].w )
        mov     ax, [dumpBoxes__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [el__w + bx]
        mov     [putField__n], ax
        call    putField
; ---- putField( el[i].h )
        mov     ax, [dumpBoxes__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [el__h + bx]
        mov     [putField__n], ax
        call    putField
; ---- putField( el[i].minW )
        mov     ax, [dumpBoxes__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [el__minW + bx]
        mov     [putField__n], ax
        call    putField
; ---- putField( el[i].minH )
        mov     ax, [dumpBoxes__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [el__minH + bx]
        mov     [putField__n], ax
        call    putField
; ---- putField( el[i].overflowX )
        mov     ax, [dumpBoxes__i]
        mov     bx, ax
        mov     al, [el__overflowX + bx]
        xor     ah, ah                      ; bool -> u16
        mov     [putField__n], ax
        call    putField
; ---- putNumber( el[i].overflowY )
        mov     ax, [dumpBoxes__i]
        mov     bx, ax
        mov     al, [el__overflowY + bx]
        xor     ah, ah                      ; bool -> u16
        mov     [putNumber__n], ax
        call    putNumber
; ---- newline()
        call    newline
.L551:
        inc     word [dumpBoxes__i]
        jmp     .L550
.L552:
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int21:
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        ret

; ============================================================ data ====

; ---- reserved globals: the machine registers ----
_ax:            dw      0
_al:            equ     _ax
_ah:            equ     _ax + 1
_bx:            dw      0
_bl:            equ     _bx
_bh:            equ     _bx + 1
_cx:            dw      0
_cl:            equ     _cx
_ch:            equ     _cx + 1
_dx:            dw      0
_dl:            equ     _dx
_dh:            equ     _dx + 1
_si:            dw      0
_di:            dw      0

; ---- variables ----
putChar__c:     db      0        ; u8
putNumber__n:   dw      0        ; u16
strLen__at:     dw      0        ; u16
strLen__ret:    dw      0        ; u16
elCount:        dw      0        ; u16
openDepth:      dw      0        ; u16
childBufLen:    dw      0        ; u16
childListLen:   dw      0        ; u16
setSize__i:     dw      0        ; u16
setSize__xAxis: db      0        ; bool
setSize__v:     dw      0        ; u16
setOverflow__i: dw      0        ; u16
setOverflow__xAxis: db      0        ; bool
build__pushElement__isCol: db      0        ; bool
